#!/usr/bin/env python3
"""Update the submission from matched 8-MW electricity, heat, NOx and community outputs.
10-MW remains a separate manufacturer power-curve proxy sensitivity; matched Wonder Valley.
"""
import json, math, re
from pathlib import Path
from docx import Document
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.table import WD_TABLE_ALIGNMENT
from docx.shared import Inches,Pt
from docx.oxml.ns import qn
from PIL import Image
HERE=Path(__file__).resolve().parent;R=HERE.parent;ROOT=R.parent;SUB=ROOT/'SUBMISSION';F=ROOT/'FIGURES';OUT=R/'OUTPUT'
S=json.loads((OUT/'storage_fuel_sweetspot.json').read_text());sw=S['sweet_spot'];rf=S['reference_selected']
PC=json.loads((OUT/'profit_community_results.json').read_text());cm=PC['comparison'];NX=json.loads((OUT/'nox_control_results.json').read_text());D=json.loads((OUT/'industrial_drying_results.json').read_text())['central'];nx=next(z for z in NX['packages'] if z['package']==NX['recommended'])
a=json.loads((HERE/'OUTPUT/SANY_SI19580_8MW_optimization.json').read_text());b=json.loads((HERE/'OUTPUT/SANY_SI230100_10MW_optimization.json').read_text());bc8=json.loads((HERE/'OUTPUT/SANY_SI19580_8MW_BC_monthly_validation.json').read_text());bc10=json.loads((HERE/'OUTPUT/SANY_SI230100_10MW_BC_monthly_validation.json').read_text())
C=a['candidate'];B=b['candidate'];e=cm['dg_facility_mt']+cm['dg_n2o_mt'];ng=cm['wv_facility_mt']; gap=PC['label_premium_needed']['sweet_spot|central_4_rising_3pct|tier_output_based'];gain=(1-sw['lcoe_25y_cad_mwh']/rf['lcoe_25y_cad_mwh'])*100
site_names=['Pennask','Mount Mabel','Nicola proxy','Cache Creek proxy','Highland Valley']

def setp(d,i,s):
 p=d.paragraphs[i];assert not p._element.xpath('.//a:blip'),(i,'image');p.text=s;p.alignment=WD_ALIGN_PARAGRAPH.CENTER if p.style.name.startswith('Heading') or i==0 else WD_ALIGN_PARAGRAPH.JUSTIFY

main=Document(SUB/'Joule_Research_Article.docx')
changes={
4:'AI data-centre developers can build large gas-powered campuses or community-integrated renewable networks. This conditional model compares 17 proposed Digital Gardens nodes in British Columbia with a matched-load Wonder Valley-type gas-campus counterfactual in Alberta. Two modern Chinese onshore turbine alternatives (SANY 8 MW and 10 MW) are independently allocated across five Global Wind Atlas-informed ridge proxies and replayed against 16 years of hourly ERA5 weather. The 8 MW scenario is carried through the heat, fuel, carbon and financial calculations; the 10 MW case tests turbine choice. Neither site-specific wind production, turbine certification at these locations, transmission deliverability nor renewable-fuel procurement has been demonstrated.',
6:(f'We compare 17 proposed Digital Gardens computing nodes in British Columbia with a Wonder Valley-type gas-campus model at 3.75 GW of IT load. A site-free wind, solar, storage and fuel search evaluates SANY 8 MW and 10 MW onshore turbine configurations across 16 ERA5 weather years corrected to Global Wind Atlas mean speeds. The 8 MW primary case has {sw["wind_GW"]:.2f} GW wind, {sw["solar_GW"]:.1f} GW solar and {sw["battery_GWh"]:.1f} GWh batteries and costs C${sw["lcoe_25y_cad_mwh"]:.0f}/MWh versus C${rf["lcoe_25y_cad_mwh"]:.0f}/MWh for a separate 300-ML-fuel renewable case and C$75–114/MWh for gas. Modelled life-cycle emissions are {e:.2f} versus {ng:.2f} Mt CO₂e/year. No gas is needed in the central 40%-cap replay, but lower wind assumptions require fossil backup. Manufacturer power curves, measured ridge wind, network deliverability and fuel contracts remain unverified.'),
14:'Table 1 uses a site-free SANY 8 MW onshore turbine engineering power-curve proxy as the Digital Gardens central case, with five independently allocatable wind zones and a maximum 40% modeled mean output per zone. The matched-load Wonder Valley-type gas comparator is a generic 57%-efficient combined-cycle model and is not a record of Wonder Valley operations. SANY 10 MW is evaluated in a separate power-curve uncertainty case. Neither output supports certified turbine-site feasibility or actual transmission-connected operation.',
15:'Table 1. Digital Gardens versus Wonder Valley-type gas campus at equal 3.75 GW IT load. The Digital Gardens column uses the SANY 8 MW conditional dispatch and linked heat, emissions, NOx and 25-year economics; the gas column is a generic modeled comparator. Reported Wonder Valley water is project-scale information, not an equal-load measurement.',
17:(f'The 17 host communities have an illustrative {cm["community_baseline_mt"]:.2f} Mt CO₂e/year baseline; adding the equal-IT-load gas campus gives {cm["ledger_wv_mt"]:.2f} Mt/year. Digital Gardens computing life-cycle emissions are {e:.2f} Mt/year including {cm["dg_n2o_mt"]:.3f} Mt of assumed SCR-related N₂O, against {ng:.2f} Mt for the gas model. Potential community emissions avoidance is separately estimated at {cm["reductions_limited_mt"]:.2f}–{cm["reductions_full_mt"]:.2f} Mt/year and is not counted as measured removal or credits. Illustrative community-plus-computing outcomes are {cm["ledger_dg_full_mt"]:.2f}–{cm["ledger_dg_limited_mt"]:.2f} Mt/year; the inputs are prospective interventions, not municipal inventories.'),
21:(f'The matched 8 MW turbine search evaluated {a["search"]["evaluations"]:,} designs across independently variable sites (0–2 GW each, Nicola limited to 0.2 GW), solar, batteries and HVO. The lowest-cost gas-free candidate found by this finite search uses {sw["wind_GW"]:.2f} GW wind ({C["turbine_count_total_ceil"]} 8-MW turbines), {sw["solar_GW"]:.2f} GW solar, {sw["battery_GWh"]:.2f} GWh batteries and an HVO allocation of {sw["fuel_cap_ML"]:.0f} ML/year. It requires {sw["hvo_ml_mean"]:.0f} ML/year on average and {sw["hvo_ml_max"]:.0f} ML in the worst historical year, plus {S["params"]["farm_hvo_ml"]:.1f} ML/year for farming. The 25-year modelled cost is C${sw["lcoe_25y_cad_mwh"]:.1f}/MWh; independently screened 8 MW capacity with a 300-ML fuel cap costs C${rf["lcoe_25y_cad_mwh"]:.1f}/MWh ({gain:.1f}% higher than the selected case). These bounds and scenario costs are not guaranteed commercial quotations or global optimisation certificates.'),
23:'Fig. 2. SANY 8 MW conditional 16-year portfolio search: independently allocated wind, solar, batteries and alternative 300-ML and 966-ML data-centre HVO ceilings. The fuel limit applies to the data centres, with farm use included in the common procurement constraint. No connection agreement, turbine-layout permit or fuel supply contract is implied.',
26:(f'The five distinct ERA5 ridge 100-m cells have raw average wind speeds of 2.96–4.29 m/s, against independently sampled 100-m Global Wind Atlas means of 4.73–10.10 m/s. A piecewise cubic engineering power curve for the SANY SI-19580 8 MW machine uses the manufacturer-stated 11.5 m/s rated speed [61], with 85% pre-electrical-output model availability and a further 6% wind loss. To prevent summit-pixel extrapolation above 40%, modeled speeds are reduced where the calculated site output exceeds a 40% screening factor. The resulting site factors are {", ".join(site_names[i]+" "+format(a["sites"][i]["screened_cf"]*100,".1f")+"%" for i in range(5))}. Optimized installed capacity is {", ".join(site_names[i]+" "+format(list(C["wind_gw_by_site"].values())[i],".2f")+" GW" for i in range(5))}. The capacity-weighted screened factor is {S["wind_benchmark_cf"]*100:.1f}%. An unverified 10 MW proxy gives a different layout and is reported separately.'),
27:(f'Global Wind Atlas means do not validate the hourly chronology of wind ramps and lulls. The 8 MW model monthly shape agrees weakly with Statistics Canada British Columbia wind generation (within-year-normalized Pearson r={bc8["all_2016_2025_r"]:.2f} for 2016–2025; r={bc8["excluding_2020_r"]:.2f} when excluding anomalous 2020 only as a sensitivity). The 2020 official observations are retained. Alberta hourly records provide out-of-region lull statistics, not local site measurements. Single raster pixels and proxy project regions cannot represent the enormous areas occupied by hundreds of turbines; turbine icing, wakes, access routes, extreme loading and actual transmission connections have not been assessed.'),
29:(f'Fig. 3. Eight- and ten-megawatt site allocations under the same 40% screened site-CF limit (Nicola ≤0.2 GW) and worst-year emergency-gas demand for each fixed installed configuration. In the 8 MW case, the same design needs {a["stress"]["cap35_same_installation"]["gas_gwh_max"]:.0f} GWh fossil backup at a 35% cap, {a["stress"]["GWA90pct_cap40"]["gas_gwh_max"]:.0f} GWh with a 10% GWA mean-wind reduction and {a["stress"]["raw_ERA5"]["gas_gwh_max"]/1000:.2f} TWh under raw ERA5; none are operating observations.'),
32:(f'The central modeled Wonder Valley-type gas comparator remains much cheaper: C$75.4/MWh under output-based TIER, C$108.5/MWh for modeled CCS from 2035 and C$113.7/MWh with the headline carbon price on every tonne. The matched 8 MW Digital Gardens network costs C${sw["lcoe_25y_cad_mwh"]:.1f}/MWh, C${gap["gap_cad_mwh"]:.1f}/MWh above the central TIER case. The independently selected 300-ML HVO renewable counterpart costs C${rf["lcoe_25y_cad_mwh"]:.1f}/MWh. An exploratory 10 MW turbine engineering-curve configuration costs C${B["cost"]["lcoe_25y_cad_mwh"]:.1f}/MWh, but the manufacturer has not published the rated wind speed used in that model and the difference cannot establish its commercial superiority.'),
34:'Fig. 4. Twenty-five-year power-cost paths for the 8 MW selected Digital Gardens network, a separate 8 MW / 300-ML HVO renewable reference, and generic Wonder Valley-type gas alternatives, in real 2026 C$/MWh.',
37:(f'The selected 8 MW Digital Gardens configuration gives {e:.2f} Mt CO₂e/year modeled computing life-cycle emissions (including SCR-related N₂O) against {ng:.2f} Mt/year from the generic same-IT-load Wonder Valley-type gas plant (Fig. 5). The screened dispatch uses no fossil gas under GWA mean-corrected 40% wind profiles, but it burns HVO/B100 renewable liquid fuel with modeled life-cycle emissions; under lower wind cases emergency fossil gas and its emissions return and are not included in this selected-scenario carbon total.'),
39:'Fig. 5. Modeled annual life-cycle emissions per GW of IT in the selected 8 MW Digital Gardens portfolio compared with an equal-load Wonder Valley-type gas model. Proposed community avoidance is shown as a separate, unverified quantity rather than certified carbon removal.',
41:(f'The modelled electricity-cost differential relative to the Wonder Valley-type central TIER gas option is C${gap["gap_cad_mwh"]:.1f}/MWh. A GPU-hour label premium adequate to cover this difference is only an algebraic break-even and not evidence that customers will pay. Transmission, hourly clean-energy traceability, fuel offtake, delivery of compute and the environmental label require independent assurance.'),
43:(f'For the selected 8 MW system, an on-demand-price break-even energy differential corresponds to approximately US${gap["premium_usd_per_gpu_h"]["GB300 NVL72"]:.2f} per NVL72 GPU-hour and US${gap["premium_usd_per_gpu_h"]["HGX B300"]:.2f} per HGX B300 GPU-hour if charged to every sold hour; applying a label premium to only half of sold hours doubles these values. Full-project NPV break-even includes GPU hardware and community costs (Table S5). No customer contracting evidence is claimed.'),
49:'Fig. 6. GPU-service financial sensitivities under the selected SANY 8 MW model and matched-load Wonder Valley-type gas alternatives. Buyer premiums, capital costs and utilisation remain conditional economic inputs.',
51:'Industrial drying has been recalculated on the selected 8 MW site allocation using the same 17 node-specific temperatures, heat-matching requirements and hourly renewable-curtailment conditions. The central full-service contracts are recomputed; other exploratory drying contract scales remain engineering assumptions and are not treated as reoptimised turbine-specific cases. Real drying routes, customer energy requirements, permits and connection capacity remain unverified.',
53:(f'The matched central case removes {D["economics"]["water_mt"]:.2f} Mt/year of water using {D["economics"]["heat_twh"]:.2f} TWh/year of drying heat, with {D["utilisation_pct"]:.1f}% utilization of recoverable IT heat and an energy reuse factor of {D["erf_pct"]:.1f}%. Drying capital is approximately C${D["economics"]["capex_bn"]*1000:.0f} million, with C${D["economics"]["customer_saving_m_cad_mean"]:.1f} million/year average hypothetical customer savings and C${D["economics"]["margin_m_cad_mean"]:.1f} million/year average supplier margin. These are conditional engineering and contracting results, not market-tested demand.'),
55:'Scaling drying contracts could raise heat use, but these high-scale scenarios are not verified projects and must not be inferred from the central 8 MW dispatch without separate contract-scale and network studies.',
60:(f'The Digital Gardens scenario uses a modeled closed liquid-cooling circuit with no consumptive evaporative cooling water, but would still reject approximately {D["rejected_twh"]:.2f} TWh/year of low-grade heat under central offtake assumptions. Waterbody thermal mixing, baseflows, environmental permits and dry-cooling performance remain unknown. Wonder Valley water figures are public project-scale projections, not equal-IT-load operating measurements.'),
64:(f'The selected 8 MW dispatch calls for approximately {NX["engine_profile"]["engine_twh"]:.2f} TWh/year of renewable liquid-fuel engine generation over {NX["engine_profile"]["hours_per_year"]:.0f} modeled operating hours/year; {NX["engine_profile"]["share_nov_feb"]*100:.0f}% occurs in November–February. These are hypothetical generator and dispatch inputs; engine-out NOx and the assumed controls have not been verified by site tests.'),
66:(f'Modelled HVO plus water-in-fuel emulsion and 97% SCR yields {nx["nox_t_yr"]:.0f} tonnes NOx/year, against approximately {NX["gas_twin_nox_t"]:.0f} tonnes for the modeled gas twin. The renewable alternative is slightly higher in this scenario and the difference is within substantial emissions-factor uncertainty. SCR efficiency and winter operating conditions require direct verification; fuel-penalising EGR/timing variants can breach the renewable-fuel ceiling and are not credited as gas-free.'),
69:'An independently verifiable clean-compute label would require actual hourly generation and consumption, certified life-cycle emissions and site-specific air-quality measurements. The conditional 8 MW/40%-cap dispatch has no emergency gas in 16 historical replays but cannot imply demonstrated renewable availability, fossil-free operation, metered emissions or physically deliverable electricity.',
74:(f'Wind and turbine technology are the primary limitations. This analysis uses approximated 8/10 MW power curves and 100-m Atlas point means, not site-specific manufacturer-warranted energy production. The selected 8 MW wind portfolio requires {C["turbine_count_total_ceil"]} turbines with an indicative rotor-spacing envelope of {C["approx_rotor_spacing_envelope_km2"]:.0f} km² before terrain exclusions. Emergency gas increases to {a["stress"]["cap35_same_installation"]["gas_gwh_max"]:.0f} GWh worst-year under a 35%-CF ceiling, {a["stress"]["GWA90pct_cap40"]["gas_gwh_max"]:.0f} GWh with 10% lower Atlas speed and {a["stress"]["raw_ERA5"]["gas_gwh_max"]/1000:.2f} TWh for raw ERA5. Monthly BC observed agreement is weak (r={bc8["all_2016_2025_r"]:.2f}), and the 10 MW option lacks a certified supplied power curve.'),
75:(f'Fuel procurement. The 8 MW selected portfolio requires {sw["hvo_ml_mean"]:.0f} ML/year HVO on average, up to {sw["hvo_ml_max"]:.0f} ML/year in the worst modeled year, and assumes {S["params"]["farm_hvo_ml"]:.1f} ML/year additional farm use. Neither sustained feedstock availability nor fuel price, transport, sustainability criteria and guaranteed year-round delivery have been established.'),
78:'Community and drying. The central heat-offtake/drying scenarios have been recalculated with the 8 MW power portfolio and remain conditional on unverified contracts, booster power deliverability, pipes, heat demand, permitting and prospective livestock-feed approvals. Exploratory high-throughput drying sensitivities are not independently reoptimised for each turbine type.',
81:(f'The modeled Wonder Valley-type equal-load gas campus consumes about {cm["gas_pj_equal_it"]:.0f} PJ/year of fossil gas and produces {ng:.2f} Mt CO₂e/year life-cycle emissions. The selected conditional SANY 8 MW Digital Gardens portfolio uses {sw["wind_GW"]:.2f} GW wind, {sw["solar_GW"]:.1f} GW solar and {sw["battery_GWh"]:.1f} GWh batteries, costing C${sw["lcoe_25y_cad_mwh"]:.0f}/MWh against gas at C$75–114/MWh; annual modeled computing life-cycle emissions are {e:.2f} Mt. A 10 MW alternative gives C${B["cost"]["lcoe_25y_cad_mwh"]:.0f}/MWh only under an assumed turbine performance curve. Neither achieves guaranteed fossil-gas-free operation under conservative wind stress or establishes physically buildable wind sites, transmission, procurement or contracted compute premiums. The 17-community benefits are additional possibilities, not verified offsets.'),
86:'Data and code availability. Source-traced GWA 100-m sampling and ERA5 hourly weather inputs, statistics on observed BC monthly wind output, the 8 MW and 10 MW turbine engineering-curve scripts, bounded site allocation, 16-year dispatch comparisons, and matched central heat, emissions, NOx and financial calculations are included. Restricted-source redistribution permissions and an immutable public DOI remain outstanding; the original Canadian wind raster was not distributed.',
89:'Sixteen annual 8,760-hour ERA5 weather replays (2010–2025) represent 17 BC computing nodes using 36.00486 TWh/year electricity. Five independent ridge proxies are mean-corrected to sampled Global Wind Atlas 100-m values; a site resource reduction enforces a 40% modeled capacity-factor limit. SANY SI-19580 8 MW (195 m rotor, cut-in 3 m/s, rated speed 11.5 m/s, cut-out 25 m/s, IEC S) and SI-230100 10 MW (230 m rotor, cut-in 3 m/s, cut-out 25 m/s, IEC S) are manufacturer-specified for key dimensions [61,62]. Because full certified power curves are not publicly provided, hourly output uses a 3-to-rated-speed cubic engineering proxy with 85% derating and an additional 6% loss. The 10 MW rated speed is assumed as 11.0 m/s and explicitly stressed at 10.5, 11.5 and 12.0 m/s; it is not an OEM quotation.',
91:(f'Separate 8 MW and 10 MW differential-evolution searches each evaluate {a["search"]["evaluations"]:,} candidate objective calls (maximum 2 GW per region, 0.2 GW Nicola) and optimise five wind capacities, solar, batteries and data-centre HVO volume against 16 historical years. A separate 8 MW/300-ML fuel comparator has an independently searched portfolio. Both primary turbine cases are dispatched under a common nominal 1,000-ML total fuel procurement ceiling including {S["params"]["farm_hvo_ml"]:.1f} ML of assumed farm use. Searchers stopped at iteration limits: no global optima or energy contracts are established. The selected 8 MW case is used for downstream drying, financial, NOx and community calculations.'),
93:(f'The selected 8 MW installed design requires maximum annual emergency fossil gas of 0 GWh under the GWA/ERA5 40%-CF screen, {a["stress"]["cap35_same_installation"]["gas_gwh_max"]:.0f} GWh under an identical-design 35%-CF screen, {a["stress"]["GWA90pct_cap40"]["gas_gwh_max"]:.0f} GWh when GWA means are reduced by 10%, and {a["stress"]["raw_ERA5"]["gas_gwh_max"]:.0f} GWh using raw ERA5 speeds. The corresponding 10 MW same-build scenarios are 0, {b["stress"]["cap35_same_installation"]["gas_gwh_max"]:.0f}, {b["stress"]["GWA90pct_cap40"]["gas_gwh_max"]:.0f} and {b["stress"]["raw_ERA5"]["gas_gwh_max"]:.0f} GWh. The 10 MW uncertainty when rated wind speed is changed to 11.5 m/s results in {b["stress"]["10MW_assumed_rated_11.5ms"]["gas_gwh_max"]:.0f} GWh worst-year gas. All inherit ERA5’s unvalidated hourly chronology.'),
95:(f'The Statistics Canada BC monthly production series supplies 120 observations for 2016–2025. Model output is averaged monthly, normalised by its mean within each year, and compared with the similarly transformed provincial actual production. Pearson r={bc8["all_2016_2025_r"]:.2f} for the 8 MW case (r={bc8["excluding_2020_r"]:.2f} if 2020 is excluded as a sensitivity); r={bc10["all_2016_2025_r"]:.2f} for 10 MW. The official 2020 series remains in the research data. The provincial fleet, built in different terrain and capacity vintages, cannot validate these five specific future ridge farms. AESO Alberta hourly generation is an independent out-of-region lull benchmark only.'),
99:(f'The modeled SANY 8 MW conditional primary scenario produces {e:.3f} Mt CO₂e/year power-system life-cycle emissions, including {cm["dg_n2o_mt"]:.3f} Mt from hypothetical engine SCR-associated N₂O, against {ng:.3f} Mt/year for the matched-load gas counterfactual. The selected emissions total excludes emergency fossil gas in adverse wind sensitivities; it must never be described as the verified annual inventory for a constructed project.'),
108:(f'The selected SANY 8 MW design generates {NX["engine_profile"]["engine_twh"]:.2f} TWh/year using modeled renewable liquid fuel engines. The assumed 97% SCR plus HVO-emulsion package produces {nx["nox_t_yr"]:.0f} tonnes NOx/year versus {NX["gas_twin_nox_t"]:.0f} tonnes for the generic gas comparator. No local ambient-air or equipment emissions evidence supports an air-quality advantage.'),
110:'The accompanying code provides resource processing, 8/10 MW turbine proxy curves, constrained wind-capacity optimisation, historical hourly dispatch, matched 8 MW central drying, NOx, life-cycle emissions, GPU economics and Wonder Valley-type counterfactuals. Separate data-vintage and farm-location verification, long-distance energy delivery, rotor-layout engineering, independent certified power curves and an immutable code-and-data DOI remain outstanding.',
112:'The model uses 16 ERA5 historical annual sequences, each with 8,760 simulated hours, and bounded differential-evolution screening searches. Correlations against British Columbia monthly actual generation are descriptive; 2020 is excluded only in a labelled sensitivity, not deleted. Confidence bounds cannot be inferred from GWA point means, an assumed turbine power curve or transposed Alberta hourly generation.'
}
