tgt=next(p for p in main.paragraphs if p.style.name=='Heading 2' and p.text=='Twenty-five years of electricity against a gas twin')
def insert_before(target,s,style=None):
 p=main.add_paragraph(s,style=style);target._p.addprevious(p._p);return p
insert_before(tgt,'Modern Chinese 8 MW and 10 MW onshore turbine alternatives','Heading 2')
insert_before(tgt,(f'SANY lists SI-19580 as an 8 MW, 195 m rotor, 11.5 m/s rated-speed onshore machine and SI-230100 as a 10 MW, 230 m rotor onshore machine [61,62]. Using separate proxy curves and independently allocatable wind zones, the 8 MW screen chooses {C["turbine_count_total_ceil"]} turbines (C${sw["lcoe_25y_cad_mwh"]:.1f}/MWh), while the speculative 10 MW proxy selects {B["turbine_count_total_ceil"]} turbines (C${B["cost"]["lcoe_25y_cad_mwh"]:.1f}/MWh). The modeled 10 MW rated wind speed of 11.0 m/s is not manufacturer-specified: changing it to 11.5 m/s, with installed capacities unchanged, yields {b["stress"]["10MW_assumed_rated_11.5ms"]["gas_gwh_max"]:.0f} GWh worst-year emergency gas. Thus the slightly lower 10 MW proxy price is not a bankable engineering result. The 7D crosswind by 5D downwind rotor-spacing envelopes are about {C["approx_rotor_spacing_envelope_km2"]:.0f} and {B["approx_rotor_spacing_envelope_km2"]:.0f} km² for the 8 MW and 10 MW cases, respectively, before construction and environmental exclusions (Table S10; Fig. S5). Actual mountain access, hub heights, turbine certification, wakes and BC grid interconnection remain unexamined.'),None)
# Manufacturer primary source additions without claiming full curve publication.
main.add_paragraph('[61] SANY Renewable Energy. SI-19580: 8-MW onshore turbine technical specification, manufacturer website. https://en.sanyre.com.cn/html/en/Product/SmartWindTurbine/7XMW8XmW/SI19580/index.html')
main.add_paragraph('[62] SANY Renewable Energy. SI-230100: 10-MW onshore turbine technical specification (rated wind speed not stated), manufacturer website. https://en.sanyre.com.cn/html/en/Product/SmartWindTurbine/8X11X/SI230100/index.html')
main.save(SUB/'Joule_Research_Article.docx')

# Fresh coherent supplemental information, 10 tables and 4 original supplemental figures retained.
si=Document(); sec=si.sections[0];sec.top_margin=Inches(.8);sec.bottom_margin=Inches(.8)
style=si.styles['Normal'];style.font.name='Aptos';style.font.size=Pt(9)
si.add_heading('Supplemental information and computational provenance',0)
si.add_paragraph('Digital Gardens versus Wonder Valley: Comparing renewable AI networks and gas-powered campuses')
si.add_paragraph('Jonathan Karl Bily | Independent Researcher, Zaragoza, Spain')
si.add_heading('Scope, inputs and reproducibility',level=1)
si.add_paragraph('The primary 8 MW wind portfolio and exploratory 10 MW alternative use a matched 3.75 GW IT load, five Global Wind Atlas 100-m ridge or proxy means and the 2010–2025 ERA5 hourly chronology. SANY product sheets supply turbine nameplate ratings, rotor diameters, cut-in and cut-out wind speeds, and the 8 MW rated wind speed. Full independently certified turbine power curves and measured local farm distributions were not provided. The 10 MW rated wind speed of 11.0 m/s is an engineering assumption and must not be attributed to the manufacturer.')
si.add_paragraph('Site capacities are selected independently under a 2 GW regional ceiling and 0.2 GW at the low-wind Nicola proxy. A 40% modeled upper mean capacity-factor screen applies to all five ridges. The battery/HVO/fossil-gas dispatch and 25-year costs follow the research-code assumptions; grid transmission, land, fuel and permitting remain unverified. Searches ended at iteration limits and do not certify an optimum. Full source code, data, comparison calculations and source URLs accompany this document.')
si.add_paragraph('The Wonder Valley comparison always uses the generic matched-load gas model with 57% combined-cycle efficiency. Its assumed emissions and costs are not measured Wonder Valley performance. Neither conditional power system is an actual project carbon inventory.')

